# BaseViewSet.initial(): for authenticated users self.queryset = self.queryset.restrict(request.user, action) -> RestrictedQuerySet.restrict():
#   superusers bypass; users without the model permission get queryset.none(); otherwise objects are filtered by the ObjectPermission constraints
#   assigned to the user/group (administrator-configured, may reference the requesting user via $user). Object-level checks also run on save().
# NetBoxModelViewSet adds bulk update/delete and change logging on top of BaseViewSet; NetBoxReadOnlyModelViewSet is list/retrieve only.

# netbox/core/api/views.py:164
class BackgroundQueueViewSet(BaseRQViewSet):
    serializer_class = serializers.BackgroundQueueSerializer

    def retrieve(self, request, name):
            data = self.get_data()
            if not data:
                raise Http404

            for queue in data:
                if queue['name'] == name:
                    serializer = self.serializer_class(queue, context={'request': request})
                    return Response(serializer.data)

            raise Http404

